 public Phase CurrentPhase{get;private set;}public bool InGame=>CurrentPhase==Phase.Fishing||CurrentPhase==Phase.Torn;public bool IsCinematic=>CurrentPhase==Phase.Travel||CurrentPhase==Phase.Casting||CurrentPhase==Phase.Landing||CurrentPhase==Phase.Leaving;public float Indicator=>Mathf.PingPong(clock*(JourneyStageLayout.Current?JourneyStageLayout.Current.fishingIndicatorSpeed:.65f),1);public float Progress{get;private set;}public float Integrity{get;private set;}=1;public int Retries{get;private set;}public bool Repented{get;private set;}public bool BoatAbandoned{get;private set;}public Transform Player=>player;public Transform Andrew=>andrew;public Transform Net=>net;public int Stage{get;private set;}
 JourneyGame game;Transform player,boat,net,andrew,jesus,peter,james,john;SpriteRenderer body,netBody;Material mat;Sprite square;Sprite[] nets,poses;GameObject environment,panel;Canvas ui;RectTransform cursor,progressFill,integrityFill;TMP_Text feedback;Transform[] fish=new Transform[28];Vector3 boatOrigin;float clock,pullMotion;bool busy,shutdown,oldPixel;UnityEngine.Rendering.Universal.PixelPerfectCamera pixel;
 public void Initialize(JourneyGame g,Transform p,SpriteRenderer b,Material m,Sprite s,int step){JourneyObjectFactory.BeginStage(this,step);game=g;player=p;body=b;mat=m;square=s;nets=JourneySpriteAssets.LoadAll("CrossTheLine/FishingNet").OrderBy(x=>x.name).ToArray();poses=JourneySpriteAssets.LoadAll("CrossTheLine/FisherActions").OrderBy(x=>x.name).ToArray();if(nets.Length!=4||poses.Length!=6)throw new Exception("Fishing net and action sprites missing");pixel=g.journeyCamera.GetComponent<UnityEngine.Rendering.Universal.PixelPerfectCamera>();if(pixel){oldPixel=pixel.enabled;pixel.enabled=false;}BuildUI();ConfigureStep(step);}
 Color C(string h){ColorUtility.TryParseHtmlString("#"+h,out var c);return c;}
 Transform Shape(string n,Transform parent,Vector3 p,Vector2 size,string color,int order=0){var o=JourneyObjectFactory.Create(n);o.transform.SetParent(parent,false);o.transform.localPosition=p;o.transform.localScale=new Vector3(size.x,size.y,1);var r=o.GetOrAddComponent<SpriteRenderer>();r.sprite=square;r.sharedMaterial=mat;r.color=C(color);r.sortingOrder=order;return o.transform;}
 Transform Shape(string n,float x,float y,float w,float h,string c,int order=0)=>Shape(n,environment.transform,new Vector3(x,y,0),new Vector2(w,h),c,order);
 void SpritePose(SpriteRenderer r,Sprite s,float height=1.85f){r.sprite=s;float scale=height/s.bounds.size.y;r.transform.localScale=Vector3.one*scale;r.transform.localPosition=new Vector3(-s.bounds.center.x*scale,-s.bounds.min.y*scale,0);}
 Transform Actor(string name,Sprite s,float x,float y){var o=JourneyObjectFactory.Create(name);o.transform.SetParent(environment.transform,false);o.transform.position=JourneyStageLayout.Point(this,o.transform,"Placement 1",new Vector3(x,y,0));var r=JourneyObjectFactory.Create("Sprite").GetOrAddComponent<SpriteRenderer>();r.transform.SetParent(o.transform,false);r.sharedMaterial=mat;r.sortingOrder=50;SpritePose(r,s);int i=Array.IndexOf(game.disciples,s);if(i>=0)r.gameObject.GetOrAddComponent<DiscipleWalking>().Initialize(i,o.transform);return o.transform;}
 void Pose(Transform t,int frame,float height=1.85f){var r=t.GetComponentInChildren<SpriteRenderer>();var walker=r.GetComponent<DiscipleWalking>();if(walker)walker.enabled=false;SpritePose(r,poses[frame],height);r.flipX=frame%3!=2;}
 Transform Boat(){var o=JourneyObjectFactory.Create("남겨 두는 배");o.transform.SetParent(environment.transform,false);var t=o.transform;Shape("나무 선체",t,new Vector3(0,-.4f,0),new Vector2(7,.8f),"85613f",35);Shape("갑판",t,Vector3.zero,new Vector2(8,.16f),"bc925f",55);for(int i=0;i<6;i++)Shape("선체 판자",t,new Vector3(0,-.75f+i*.13f,0),new Vector2(6.5f+i*.2f,.04f),"b18a5b",36);Shape("돛대",t,new Vector3(.4f,1.7f,0),new Vector2(.09f,3.4f),"795a3b",30);Shape("돛",t,new Vector3(1.45f,2.35f,0),new Vector2(2,1.1f),"e9ddbf",29);return t;}
 public void ConfigureStep(int step){JourneyObjectFactory.BeginStage(this,step);Stage=Mathf.Min(step,6);clock=0;busy=false;pullMotion=0;if(environment)Destroy(environment);environment=JourneyObjectFactory.Create("GalileeCatchEnvironment");environment.transform.SetParent(transform,false);Shape("호수",0,0,35,20,Stage==1||Stage==2||Stage==3?"3b7789":"77a6a8",-10);Shape("하늘",0,4,35,4,"d8d6b4",-9);for(int i=0;i<32;i++)Shape("잔물결",-12+i%8*3.5f,2-i/8*1.4f,1.3f,.025f,"a1c2bf",-7);if(Stage==0||Stage>=4)Shape("얕은 물과 물가",0,-3.4f,35,3.4f,"c7b98b",-6);boat=Boat();boat.position=JourneyStageLayout.Point(this,boat,"Placement 2",new Vector3(Stage==0?3:0,Stage>=5?.8f:-.6f,0));boatOrigin=boat.position;
 andrew=Actor("안드레",game.disciples[1],-1,-.55f);jesus=Actor("배에 계신 예수님",game.jesusFrames[0],2,-.55f);peter=Actor("베드로",game.disciples[0],-2,-.55f);james=Actor("야고보",game.disciples[2],6,-2.9f);john=Actor("요한",game.disciples[3],7.5f,-2.7f);james.gameObject.SetActive(Stage>=5);john.gameObject.SetActive(Stage>=5);
 var n=JourneyObjectFactory.Create("실제 그물");n.transform.SetParent(environment.transform,false);net=n.transform;netBody=n.GetOrAddComponent<SpriteRenderer>();netBody.sharedMaterial=mat;netBody.sortingOrder=45;SetNet(0);net.position=JourneyStageLayout.Point(this,net,"Placement 3",new Vector3(-4,-1.5f,0));for(int i=0;i<fish.Length;i++){fish[i]=Shape("물고기 "+i,net,new Vector3((i%7-3)*.12f,(i/7-1.5f)*.11f,0),new Vector2(.12f,.05f),i%2==0?"bfd6c9":"e0cf8d",44);Shape("꼬리",fish[i],new Vector3(-.6f,0,0),new Vector2(.3f,1.6f),"94b2b4",44);fish[i].gameObject.SetActive(Stage>=3);}
 if(Stage==0){CurrentPhase=Phase.Shore;player.position=JourneyStageLayout.Point(this,player,"Placement 4",new Vector3(-4,-3,0));andrew.position=JourneyStageLayout.Point(this,andrew,"Placement 5",new Vector3(4,-1,0));peter.position=JourneyStageLayout.Point(this,peter,"Placement 6",new Vector3(2.4f,-1,0));jesus.gameObject.SetActive(false);net.position=JourneyStageLayout.Point(this,net,"Placement 7",new Vector3(5,-2,0));}else if(Stage==1){CurrentPhase=Phase.Travel;player.position=JourneyStageLayout.Point(this,player,"Placement 8",new Vector3(-2,-.5f,0));peter.gameObject.SetActive(false);boat.position=JourneyStageLayout.Point(this,boat,"Placement 9",new Vector3(-5,-.6f,0));}else if(Stage==2){CurrentPhase=Phase.Cast;player.position=JourneyStageLayout.Point(this,player,"Placement 10",new Vector3(-2,-.5f,0));peter.gameObject.SetActive(false);Progress=0;Integrity=1;}else if(Stage==3){CurrentPhase=Phase.Kneel;Repented=true;player.position=JourneyStageLayout.Point(this,player,"Placement 11",new Vector3(-1.8f,-.5f,0));peter.gameObject.SetActive(false);PosePlayer(2,1.25f);Pose(andrew,5,1.25f);SetNet(1);net.position=JourneyStageLayout.Point(this,net,"Placement 12",new Vector3(-3,.1f,0));}else if(Stage==4){CurrentPhase=Phase.Return;player.position=JourneyStageLayout.Point(this,player,"Placement 13",new Vector3(-2,-.5f,0));peter.gameObject.SetActive(false);SetNet(1);}else if(Stage==5){CurrentPhase=Phase.Follow;BoatAbandoned=true;player.position=JourneyStageLayout.Point(this,player,"Placement 14",new Vector3(-4,-3.1f,0));jesus.gameObject.SetActive(false);peter.position=JourneyStageLayout.Point(this,peter,"Placement 15",new Vector3(-5.5f,-2.9f,0));andrew.position=JourneyStageLayout.Point(this,andrew,"Placement 16",new Vector3(-6.8f,-2.8f,0));SetNet(1);net.position=boat.position+new Vector3(-2,.1f,0);}else{CurrentPhase=Phase.Meet;BoatAbandoned=true;player.position=JourneyStageLayout.Point(this,player,"Placement 17",new Vector3(3,-3.1f,0));jesus.gameObject.SetActive(false);peter.position=JourneyStageLayout.Point(this,peter,"Placement 18",new Vector3(1.5f,-2.9f,0));andrew.position=JourneyStageLayout.Point(this,andrew,"Placement 19",new Vector3(.1f,-2.8f,0));SetNet(1);net.position=boat.position+new Vector3(-2,.1f,0);}
 game.journeyCamera.orthographicSize=5.625f;UpdateCamera();game.BaptismCinema(IsCinematic);panel.SetActive(false);Hud();}
 void SetNet(int i){netBody.sprite=nets[i];float s=3.8f/nets[i].bounds.size.x;net.localScale=Vector3.one*s;}
 void PosePlayer(int index,float height=1.85f){var walk=body.GetComponent<DiscipleWalking>();if(walk)walk.enabled=false;SpritePose(body,poses[index],height);body.flipX=index!=2;}
 void Hud(){string[] goals={"밤새 빈 그물 · 베드로와 안드레 만나기","베드로 시점 · 깊은 물로 출항","베드로 시점 · 그물을 던지고 당기기","두 형제가 무릎 꿇고 죄를 고백하기","배를 몰아 얕은 물로 돌아가기","배와 그물과 물고기를 남겨 두고 따르기","길에서 야고보와 요한 만나기"};game.FishingHud(goals[Stage],CurrentPhase==Phase.Return?"A / ← · 배를 물가로 몰기":CurrentPhase==Phase.Follow?"D / → · 예수님의 길을 따라 걷기":CurrentPhase==Phase.Torn?"그물이 찢어졌습니다 · E / R 다시 던지기":CurrentPhase==Phase.Fishing?"초록 구간에서 E / Space · 당기기":"E · 이야기 / 그물 던지기    WASD · 이동");}
 public void Tick(float dt,bool canMove,bool press){if(!canMove&&!IsCinematic)return;clock+=dt;pullMotion=Mathf.Max(0,pullMotion-dt);if(CurrentPhase==Phase.Travel){boat.position=Vector3.Lerp(new Vector3(-5,-.6f,0),new Vector3(0,-.6f,0),Mathf.Clamp01(clock/4));player.position=boat.position+new Vector3(-2,.1f,0);andrew.position=boat.position+new Vector3(-.4f,.1f,0);jesus.position=boat.position+new Vector3(2,.1f,0);if(clock>=4)game.BaptismAdvance();return;}if(CurrentPhase==Phase.Casting){PosePlayer(0);net.position=Vector3.Lerp(new Vector3(-2,.2f,0),new Vector3(-4.5f,-2,0),Mathf.Clamp01(clock/1.4f));net.rotation=Quaternion.Euler(0,0,Mathf.Sin(clock*4)*12);if(clock>=1.5f){CurrentPhase=Phase.Fishing;clock=0;game.BaptismCinema(false);panel.SetActive(true);Hud();}return;}if(CurrentPhase==Phase.Fishing){cursor.anchorMin=new Vector2(Indicator,0);cursor.anchorMax=new Vector2(Indicator+.012f,1);if(press)AttemptPull();net.position=JourneyStageLayout.Point(this,net,"Placement 20",new Vector3(-4.5f+Progress*1.5f,-2+Progress*1.7f+Mathf.Sin(Time.time*3)*.03f,0));net.rotation=Quaternion.Euler(0,0,pullMotion>0?-8:0);PosePlayer(pullMotion>0?1:0);Pose(andrew,pullMotion>0?4:3);player.position=JourneyStageLayout.Point(this,player,"Placement 21",new Vector3(-2-(pullMotion>0?.15f:0),-.5f,0));foreach(var f in fish)f.gameObject.SetActive(true);ProgressUI();return;}if(CurrentPhase==Phase.Torn){foreach(var f in fish)f.localPosition+=new Vector3(0,-dt*.5f,0);if(press||(Keyboard.current!=null&&Keyboard.current.rKey.wasPressedThisFrame))Retry();return;}if(CurrentPhase==Phase.Landing){net.position=Vector3.Lerp(new Vector3(-3,-.3f,0),new Vector3(-2,.7f,0),Mathf.Clamp01(clock/2));if(clock>=2.3f)game.BaptismAdvance();return;}if(CurrentPhase==Phase.Leaving){player.position+=Vector3.right*dt*2.4f;peter.position=Vector3.MoveTowards(peter.position,player.position+new Vector3(-1.2f,.15f,0),dt*3);andrew.position=Vector3.MoveTowards(andrew.position,peter.position+new Vector3(-1.2f,.15f,0),dt*3);james.position=Vector3.MoveTowards(james.position,andrew.position+new Vector3(-1.2f,.15f,0),dt*3);john.position=Vector3.MoveTowards(john.position,james.position+new Vector3(-1.2f,.15f,0),dt*3);game.MeetingWalk(true,1);if(clock>=4){CurrentPhase=Phase.Complete;game.BaptismCinema(false);game.BaptismAdvance();}return;}
 var k=Keyboard.current;float x=k==null?0:(k.dKey.isPressed||k.rightArrowKey.isPressed?1:0)-(k.aKey.isPressed||k.leftArrowKey.isPressed?1:0);if(CurrentPhase==Phase.Return){boat.position+=Vector3.right*x*dt*2.8f;boat.position=JourneyStageLayout.Point(this,boat,"Placement 22",new Vector3(Mathf.Clamp(boat.position.x,-5,1),-.6f,0));player.position=boat.position+new Vector3(-2,.1f,0);andrew.position=boat.position+new Vector3(-.4f,.1f,0);jesus.position=boat.position+new Vector3(2,.1f,0);net.position=boat.position+new Vector3(-3,.2f,0);if(boat.position.x<=-4.8f)game.BaptismAdvance();}else if(CurrentPhase==Phase.Follow||CurrentPhase==Phase.Meet||CurrentPhase==Phase.Shore){player.position+=Vector3.right*x*dt*3.4f;player.position=JourneyStageLayout.Point(this,player,"Placement 23",new Vector3(Mathf.Clamp(player.position.x,-8,8),-3.1f,0));game.MeetingWalk(x!=0,x);if(Stage>=5){peter.position=Vector3.MoveTowards(peter.position,player.position+new Vector3(-1.3f,.2f,0),dt*3.4f);andrew.position=Vector3.MoveTowards(andrew.position,peter.position+new Vector3(-1.3f,.2f,0),dt*3.4f);if(Stage==5&&player.position.x>=3.5f)game.BaptismAdvance();}}Hud();if(press)Interact();}
 public void AttemptPull(){if(CurrentPhase!=Phase.Fishing)return;float half=JourneyStageLayout.Current?JourneyStageLayout.Current.fishingTimingHalfWidth:.14f;bool good=Mathf.Abs(Indicator-.5f)<=half;pullMotion=.28f;if(good){Progress=Mathf.Min(1,Progress+1f/(JourneyStageLayout.Current?Mathf.Max(1,JourneyStageLayout.Current.fishingPullsRequired):6));SetNet(1);feedback.text="함께 당겼습니다!";}else{Integrity=Mathf.Max(0,Integrity-.34f);SetNet(Integrity>0?2:3);feedback.text="타이밍이 빗나갔습니다 · 그물 손상";}if(Integrity<=0){CurrentPhase=Phase.Torn;SetNet(3);feedback.text="그물이 찢어졌습니다! E / R로 다시 던지세요";Hud();}else if(Progress>=1){CurrentPhase=Phase.Landing;clock=0;panel.SetActive(false);SetNet(1);game.BaptismCinema(true);}ProgressUI();}
 public void Retry(){if(CurrentPhase!=Phase.Torn)return;Retries++;Progress=0;Integrity=1;StartCast();}
 void StartCast(){feedback.text="초록 구간에서 E / Space · 그물을 함께 당기세요";CurrentPhase=Phase.Casting;clock=0;SetNet(0);panel.SetActive(false);for(int i=0;i<fish.Length;i++){fish[i].localPosition=new Vector3((i%7-3)*.12f,(i/7-1.5f)*.11f,0);fish[i].gameObject.SetActive(false);}game.BaptismCinema(true);}
 public void Interact(){if(busy||IsCinematic||InGame||CurrentPhase==Phase.Return||CurrentPhase==Phase.Follow||CurrentPhase==Phase.Complete)return;if(Stage==0&&player.position.x<.5f)return;if(Stage==6&&Mathf.Abs(player.position.x-6)>2.3f)return;busy=true;game.MeetingTalk(()=>{busy=false;if(Stage==2)StartCast();else if(Stage==6){CurrentPhase=Phase.Leaving;clock=0;game.BaptismCinema(true);}else game.BaptismAdvance();});}
 void BuildUI(){var o=JourneyObjectFactory.Create("NetTimingUI",typeof(RectTransform),typeof(Canvas),typeof(CanvasScaler));o.transform.SetParent(transform,false);ui=o.GetComponent<Canvas>();ui.renderMode=RenderMode.ScreenSpaceOverlay;ui.sortingOrder=90;var scale=o.GetComponent<CanvasScaler>();scale.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scale.referenceResolution=new Vector2(1440,900);panel=Box(o.transform,"그물 타이밍",new Vector2(.56f,.14f),new Vector2(.96f,.34f),C("eee0c1")).gameObject;var track=Box(panel.transform,"타이밍",new Vector2(.06f,.52f),new Vector2(.94f,.62f),C("596b68"));Box(track,"초록 구간",new Vector2(.36f,0),new Vector2(.64f,1),C("659d68"));cursor=Box(track,"표시",new Vector2(0,0),new Vector2(.012f,1),C("edc66b"));progressFill=Box(panel.transform,"당긴 정도",new Vector2(.06f,.35f),new Vector2(.06f,.43f),C("498b88"));integrityFill=Box(panel.transform,"그물 상태",new Vector2(.06f,.20f),new Vector2(.94f,.28f),C("bb8950"));var text=JourneyObjectFactory.Create("안내",typeof(RectTransform));text.transform.SetParent(panel.transform,false);var r=text.GetComponent<RectTransform>();r.anchorMin=new Vector2(.06f,.68f);r.anchorMax=new Vector2(.94f,.95f);r.offsetMin=r.offsetMax=Vector2.zero;feedback=text.GetOrAddComponent<TextMeshProUGUI>();feedback.font=game.koreanFont;feedback.fontSize=18;feedback.color=C("334b48");feedback.text="초록 구간에서 E / Space · 그물을 함께 당기세요";}
 RectTransform Box(Transform p,string n,Vector2 min,Vector2 max,Color c){var o=JourneyObjectFactory.Create(n,typeof(RectTransform),typeof(Image));o.transform.SetParent(p,false);var r=o.GetComponent<RectTransform>();r.anchorMin=min;r.anchorMax=max;r.offsetMin=r.offsetMax=Vector2.zero;o.GetComponent<Image>().color=c;return r;}
 void ProgressUI(){progressFill.anchorMax=new Vector2(.06f+.88f*Progress,.43f);integrityFill.anchorMax=new Vector2(.06f+.88f*Integrity,.28f);}
 void LateUpdate(){if(ui)ui.enabled=game.Mode!="menu"&&game.Mode!="dialogue"&&game.Mode!="chapter_end";if(Stage==3&&body){PosePlayer(2,1.25f);Pose(andrew,5,1.25f);}}
 public void UpdateCamera(){game.journeyCamera.transform.position=JourneyStageLayout.Point(this,game.journeyCamera.transform,"Placement 24",new Vector3(0,0,-10));}
 public void Shutdown(){if(shutdown)return;shutdown=true;if(pixel)pixel.enabled=oldPixel;}
 void OnDestroy(){Shutdown();}
